const data = $input.first().json;
const items = data.specials?.items ?? [];

const MIN_DISCOUNT = 50; // desconto mínimo em %
const store = $getWorkflowStaticData('global');
const seen = store.seen ?? {};

const brl = (v) => 'R$ ' + (v / 100).toFixed(2).replace('.', ',');
const embeds = [];

for (const g of items) {
  if (g.discount_percent < MIN_DISCOUNT) continue;

  const key = `${g.id}-${g.discount_percent}`;
  if (seen[key]) continue;
  seen[key] = Date.now();

  embeds.push({
    title: g.name,
    url: `https://store.steampowered.com/app/${g.id}`,
    description: `🔥 **-${g.discount_percent}%**  ~~${brl(g.original_price)}~~ → **${brl(g.final_price)}**`,
    color: 0x66c0f4,
    thumbnail: { url: g.small_capsule_image },
  });
}

// limpa registros com mais de 14 dias
const limit = Date.now() - 14 * 24 * 60 * 60 * 1000;
for (const k in seen) if (seen[k] < limit) delete seen[k];
store.seen = seen;

if (embeds.length === 0) return [];

// Discord aceita no máximo 10 embeds por mensagem
const out = [];
for (let i = 0; i < embeds.length; i += 10) {
  out.push({
    json: {
      payload: {
        username: 'Promoções Steam',
        content: i === 0 ? `🕹️ **${embeds.length} promoções novas na Steam**` : '',
        embeds: embeds.slice(i, i + 10),
      },
    },
  });
}
return out;
